/* ---------------------------------------------------------------------------
 * 自動補齊 audio 欄位（命名規則需與 generate_grammar_audio.py 一致）
 *   S01 matrix  : ./audio/grammar/S01_t1.mp3 ~ _t3.mp3
 *   S01 keigo   : ./audio/grammar/S01_k1.mp3 ~ _kN.mp3
 *   U01 範例    : ./audio/grammar/U01_s{段落序號}_e{範例序號}.mp3（序號從 1 起算）
 * ------------------------------------------------------------------------ */
(function () {
  var db = window.GRAMMAR_DB;
  db.scenarios.forEach(function (s) {
    ["tier1", "tier2", "tier3"].forEach(function (t, i) {
      if (s.matrix[t] && !s.matrix[t].audio) s.matrix[t].audio = "./audio/grammar/" + s.id + "_t" + (i + 1) + ".mp3";
    });
    (s.receptiveKeigo || []).forEach(function (k, i) {
      if (!k.audio) k.audio = "./audio/grammar/" + s.id + "_k" + (i + 1) + ".mp3";
    });
  });
  db.vaultUnits.forEach(function (u) {
    (u.sections || []).forEach(function (sec, si) {
      (sec.examples || []).forEach(function (ex, ei) {
        if (!ex.audio) ex.audio = "./audio/grammar/" + u.id + "_s" + (si + 1) + "_e" + (ei + 1) + ".mp3";
      });
    });
  });
})();
